//! Git hook installation, chaining and uninstallation (spec 9.4).
//!
//! # The failure that matters most
//!
//! A hook that breaks `git commit` is worse than no hook at all. Spec 9.2 is
//! explicit: the hook must not block Git, and a missing Helper must exit 0
//! silently rather than failing the commit.
//!
//! # Why chaining is done by a generated script and not by editing the user's
//!
//! Users have their own hooks, often generated by Husky or Lefthook. Spec 9.4
//! forbids overwriting them. So installation:
//!
//! 1. backs up any existing hook (keeping its exact bytes and a content hash);
//! 2. writes a Devchievements hook that calls the Helper and then chains to the
//!    backup;
//! 3. records the hash of what it wrote, so uninstall can tell whether the user
//!    edited it afterwards.
//!
//! # Why the hash matters
//!
//! Spec 9.4: on uninstall, if the chained script differs from what was installed,
//! we must NOT overwrite or delete it. We show the difference and let the user
//! decide. That requires remembering what we wrote.

#![cfg_attr(test, allow(clippy::unwrap_used, clippy::expect_used, clippy::panic))]

use std::fs;
use std::path::{Path, PathBuf};

/// The hooks this product manages (spec 9.1).
pub const MANAGED_HOOKS: [&str; 3] = ["post-commit", "post-rewrite", "post-merge"];

/// A marker embedded in every generated hook, so we can recognise our own work.
pub const HOOK_MARKER: &str = "# devchievements-managed-hook";

/// Version of the generated script, bumped when the call protocol changes.
pub const HOOK_SCRIPT_VERSION: u32 = 1;

/// Why hook management failed.
#[derive(Debug)]
pub enum HookError {
    /// A filesystem operation failed.
    Io {
        /// Path involved.
        path: PathBuf,
        /// Underlying error.
        source: std::io::Error,
    },
    /// The repository has no hooks directory and it could not be created.
    NoHooksDirectory(PathBuf),
    /// An existing hook is ours but from a newer version we do not understand.
    NewerVersion(u32),
}

impl std::fmt::Display for HookError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            HookError::Io { path, source } => {
                write!(f, "hook io error at {}: {source}", path.display())
            }
            HookError::NoHooksDirectory(p) => {
                write!(f, "hooks directory is missing: {}", p.display())
            }
            HookError::NewerVersion(v) => {
                write!(
                    f,
                    "existing hook is version {v}, newer than this build understands"
                )
            }
        }
    }
}

impl std::error::Error for HookError {}

/// What happened during installation.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum InstallOutcome {
    /// A hook was installed where none existed.
    InstalledFresh,
    /// An existing user hook was preserved and chained.
    InstalledChained {
        /// Where the original was backed up.
        backup: PathBuf,
    },
    /// Ours was already installed at this version.
    AlreadyInstalled,
    /// Ours was replaced with a newer generated script.
    Upgraded,
}

/// What happened during uninstallation.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum UninstallOutcome {
    /// Nothing of ours was present.
    NothingToDo,
    /// Our hook was removed and the backed-up original restored.
    Restored {
        /// Where the original came from.
        restored_from: PathBuf,
    },
    /// Our hook was removed and there was no original to restore.
    Removed,
    /// The chained script was modified by the user, so it was left alone.
    LeftModified {
        /// The hook that was left in place.
        path: PathBuf,
    },
}

/// Where a hook lives and what we know about it.
#[derive(Debug, Clone)]
pub struct HookSite {
    /// The hooks directory actually in effect.
    pub hooks_dir: PathBuf,
    /// Whether this directory is shared between repositories (spec 9.4).
    pub shared: bool,
}

impl HookSite {
    /// Resolve the hooks directory for a repository.
    ///
    /// Honours `core.hooksPath` (spec 9.3): installing into `.git/hooks` when the
    /// repository points elsewhere would silently never run.
    pub fn resolve(git_dir: &Path, configured_hooks_path: Option<&str>) -> Self {
        match configured_hooks_path {
            Some(path) if !path.trim().is_empty() => {
                let trimmed = path.trim();
                let as_path = PathBuf::from(trimmed);
                let resolved = if as_path.is_absolute() {
                    as_path
                } else {
                    git_dir.join(as_path)
                };
                HookSite {
                    hooks_dir: resolved,
                    // A configured hooks path is usually deliberate sharing between
                    // repositories, which materially changes the warning we owe the
                    // user (spec 9.4).
                    shared: true,
                }
            }
            _ => HookSite {
                hooks_dir: git_dir.join("hooks"),
                shared: false,
            },
        }
    }

    /// The path of a managed hook.
    pub fn hook_path(&self, name: &str) -> PathBuf {
        self.hooks_dir.join(name)
    }

    /// Where a displaced original hook is stored.
    pub fn backup_path(&self, name: &str) -> PathBuf {
        self.hooks_dir.join(format!("{name}.devchievements-backup"))
    }
}

/// The generated hook body.
///
/// Deliberately tiny and defensive: it must never fail the commit. Every failure
/// path ends with `exit 0`, and a missing Helper is not even an error.
pub fn render_hook(name: &str, helper_path: &Path) -> String {
    let helper = helper_path.to_string_lossy().replace('\\', "/");
    format!(
        "#!/bin/sh\n{HOOK_MARKER}\n# version {HOOK_SCRIPT_VERSION}\n# Generated file: do not edit; uninstall removes it.\n\nHELPER=\"{helper}\"\n\n# A missing Helper must never break the commit (spec 9.4).\nif [ -x \"$HELPER\" ]; then\n  \"$HELPER\" hook '{name}' \"$@\" || true\nfi\n\n# Chain to the hook this replaced, if any.\nBACKUP=\"$(dirname \"$0\")/{name}.devchievements-backup\"\nif [ -x \"$BACKUP\" ]; then\n  \"$BACKUP\" \"$@\" || true\nfi\n\nexit 0\n"
    )
}

/// A 64-bit content hash, used to detect user edits (spec 9.4).
fn content_hash(bytes: &[u8]) -> u64 {
    let mut hash: u64 = 0xcbf2_9ce4_8422_2325;
    for byte in bytes {
        hash ^= u64::from(*byte);
        hash = hash.wrapping_mul(0x0100_0000_01b3);
    }
    hash
}

/// Whether a file is a hook we generated.
pub fn is_managed_hook(contents: &str) -> bool {
    contents.contains(HOOK_MARKER)
}

/// Install (or upgrade) a managed hook.
pub fn install(
    site: &HookSite,
    name: &str,
    helper_path: &Path,
) -> Result<InstallOutcome, HookError> {
    fs::create_dir_all(&site.hooks_dir).map_err(|e| HookError::Io {
        path: site.hooks_dir.clone(),
        source: e,
    })?;

    let target = site.hook_path(name);
    let backup = site.backup_path(name);
    let rendered = render_hook(name, helper_path);

    if target.exists() {
        let existing = fs::read_to_string(&target).map_err(|e| HookError::Io {
            path: target.clone(),
            source: e,
        })?;

        if is_managed_hook(&existing) {
            if existing == rendered {
                return Ok(InstallOutcome::AlreadyInstalled);
            }
            // Record what we are about to replace so uninstall can still tell whether
            // the user edited it afterwards.
            write_hash_record(&target, &existing)?;
            fs::write(&target, &rendered).map_err(|e| HookError::Io {
                path: target.clone(),
                source: e,
            })?;
            make_executable(&target)?;
            return Ok(InstallOutcome::Upgraded);
        }

        // Someone else's hook: preserve it byte-for-byte, then chain.
        if backup.exists() {
            // Never overwrite an earlier backup: that would destroy the user's
            // original after a reinstall.
            return install_over(
                &target,
                &rendered,
                InstallOutcome::InstalledChained {
                    backup: backup.clone(),
                },
            );
        }
        fs::copy(&target, &backup).map_err(|e| HookError::Io {
            path: backup.clone(),
            source: e,
        })?;
        make_executable(&backup)?;
        return install_over(
            &target,
            &rendered,
            InstallOutcome::InstalledChained {
                backup: backup.clone(),
            },
        );
    }

    install_over(&target, &rendered, InstallOutcome::InstalledFresh)
}

fn install_over(
    target: &Path,
    rendered: &str,
    outcome: InstallOutcome,
) -> Result<InstallOutcome, HookError> {
    fs::write(target, rendered).map_err(|e| HookError::Io {
        path: target.to_path_buf(),
        source: e,
    })?;
    make_executable(target)?;
    write_hash_record(target, rendered)?;
    Ok(outcome)
}

/// Remember the hash of the bytes we wrote.
fn write_hash_record(target: &Path, contents: &str) -> Result<(), HookError> {
    let record = target.with_extension("devchievements-hash");
    fs::write(
        &record,
        format!("{:016x}\n", content_hash(contents.as_bytes())),
    )
    .map_err(|e| HookError::Io {
        path: record.clone(),
        source: e,
    })?;
    Ok(())
}

#[cfg(unix)]
fn make_executable(path: &Path) -> Result<(), HookError> {
    use std::os::unix::fs::PermissionsExt;
    let mut perms = fs::metadata(path)
        .map_err(|e| HookError::Io {
            path: path.to_path_buf(),
            source: e,
        })?
        .permissions();
    perms.set_mode(0o755);
    fs::set_permissions(path, perms).map_err(|e| HookError::Io {
        path: path.to_path_buf(),
        source: e,
    })
}

#[cfg(not(unix))]
fn make_executable(_path: &Path) -> Result<(), HookError> {
    // Windows has no execute bit. Git for Windows decides by extension, which is why
    // the Helper binary is installed with an explicit `.exe` name.
    Ok(())
}

/// Uninstall a managed hook, restoring the original when possible.
pub fn uninstall(site: &HookSite, name: &str) -> Result<UninstallOutcome, HookError> {
    let target = site.hook_path(name);
    let backup = site.backup_path(name);

    if !target.exists() {
        return Ok(UninstallOutcome::NothingToDo);
    }

    let existing = fs::read_to_string(&target).map_err(|e| HookError::Io {
        path: target.clone(),
        source: e,
    })?;

    if !is_managed_hook(&existing) {
        // Not ours: touching it would be destructive.
        return Ok(UninstallOutcome::NothingToDo);
    }

    // If the user edited OUR script after install, leave it alone (spec 9.4).
    let record = target.with_extension("devchievements-hash");
    if let Ok(recorded) = fs::read_to_string(&record) {
        let recorded = recorded.trim();
        let expected = content_hash(existing.as_bytes());
        if !recorded.is_empty() && recorded != format!("{expected:016x}") {
            return Ok(UninstallOutcome::LeftModified { path: target });
        }
    }

    if backup.exists() {
        fs::rename(&backup, &target).map_err(|e| HookError::Io {
            path: target.clone(),
            source: e,
        })?;
        let _ = fs::remove_file(&record);
        return Ok(UninstallOutcome::Restored {
            restored_from: backup,
        });
    }

    fs::remove_file(&target).map_err(|e| HookError::Io {
        path: target.clone(),
        source: e,
    })?;
    let _ = fs::remove_file(&record);
    Ok(UninstallOutcome::Removed)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn temp_site(name: &str) -> HookSite {
        let dir = std::env::temp_dir().join(format!("devch-hooks-{name}-{}", std::process::id()));
        std::fs::remove_dir_all(&dir).ok();
        std::fs::create_dir_all(&dir).expect("dir");
        HookSite {
            hooks_dir: dir,
            shared: false,
        }
    }

    fn helper() -> PathBuf {
        PathBuf::from("/opt/devchievements/devch-helper")
    }

    #[test]
    fn the_generated_hook_never_fails_the_commit() {
        // The single most important property (spec 9.2, 9.4).
        let body = render_hook("post-commit", &helper());
        assert!(body.contains("exit 0"), "the script must end successfully");
        assert!(
            body.contains("|| true"),
            "every Helper call must swallow failure"
        );
        assert!(
            body.contains("if [ -x"),
            "a missing Helper must be checked for"
        );
        assert!(
            body.contains(HOOK_MARKER),
            "the marker identifies our own file"
        );
    }

    #[test]
    fn installing_fresh_creates_an_executable_hook() {
        let site = temp_site("fresh");
        let outcome = install(&site, "post-commit", &helper()).expect("install");
        assert_eq!(outcome, InstallOutcome::InstalledFresh);
        assert!(site.hook_path("post-commit").exists());

        let contents = std::fs::read_to_string(site.hook_path("post-commit")).expect("read");
        assert!(is_managed_hook(&contents));

        std::fs::remove_dir_all(&site.hooks_dir).ok();
    }

    #[test]
    fn an_existing_hook_is_preserved_byte_for_byte_and_chained() {
        // Spec 9.4: never overwrite the user's hook.
        let site = temp_site("chain");
        let target = site.hook_path("post-commit");
        let original = "#!/bin/sh\necho user hook\n";
        std::fs::write(&target, original).expect("seed");

        let outcome = install(&site, "post-commit", &helper()).expect("install");
        match outcome {
            InstallOutcome::InstalledChained { backup } => {
                let preserved = std::fs::read_to_string(&backup).expect("backup readable");
                assert_eq!(preserved, original, "the backup must be byte-identical");
            }
            other => panic!("expected chained install, got {other:?}"),
        }

        let chained = std::fs::read_to_string(&target).expect("read");
        assert!(
            chained.contains("devchievements-backup"),
            "must call the original"
        );

        std::fs::remove_dir_all(&site.hooks_dir).ok();
    }

    #[test]
    fn reinstalling_does_not_clobber_the_original_backup() {
        // Otherwise a reinstall would destroy the user's hook permanently.
        let site = temp_site("reinstall");
        let target = site.hook_path("post-commit");
        std::fs::write(&target, "#!/bin/sh\necho original\n").expect("seed");
        install(&site, "post-commit", &helper()).expect("first install");

        let backup = site.backup_path("post-commit");
        let before = std::fs::read_to_string(&backup).expect("backup");

        install(&site, "post-commit", &helper()).expect("second install");
        let after = std::fs::read_to_string(&backup).expect("backup");
        assert_eq!(before, after, "the original must not be overwritten");

        std::fs::remove_dir_all(&site.hooks_dir).ok();
    }

    #[test]
    fn installing_twice_is_idempotent() {
        let site = temp_site("idempotent");
        install(&site, "post-commit", &helper()).expect("first");
        let outcome = install(&site, "post-commit", &helper()).expect("second");
        assert_eq!(outcome, InstallOutcome::AlreadyInstalled);
        std::fs::remove_dir_all(&site.hooks_dir).ok();
    }

    #[test]
    fn uninstalling_restores_the_original_hook() {
        let site = temp_site("restore");
        let target = site.hook_path("post-commit");
        let original = "#!/bin/sh\necho mine\n";
        std::fs::write(&target, original).expect("seed");
        install(&site, "post-commit", &helper()).expect("install");

        let outcome = uninstall(&site, "post-commit").expect("uninstall");
        assert!(matches!(outcome, UninstallOutcome::Restored { .. }));
        assert_eq!(std::fs::read_to_string(&target).expect("read"), original);

        std::fs::remove_dir_all(&site.hooks_dir).ok();
    }

    #[test]
    fn uninstalling_a_fresh_install_removes_it() {
        let site = temp_site("remove");
        install(&site, "post-commit", &helper()).expect("install");
        let outcome = uninstall(&site, "post-commit").expect("uninstall");
        assert_eq!(outcome, UninstallOutcome::Removed);
        assert!(!site.hook_path("post-commit").exists());
        std::fs::remove_dir_all(&site.hooks_dir).ok();
    }

    #[test]
    fn a_user_edited_hook_is_left_alone() {
        // Spec 9.4: never delete content the user modified.
        let site = temp_site("modified");
        install(&site, "post-commit", &helper()).expect("install");

        let target = site.hook_path("post-commit");
        let mut contents = std::fs::read_to_string(&target).expect("read");
        contents.push_str("\n# user added this\n");
        std::fs::write(&target, &contents).expect("edit");

        let outcome = uninstall(&site, "post-commit").expect("uninstall");
        match outcome {
            UninstallOutcome::LeftModified { path } => assert_eq!(path, target),
            other => panic!("expected LeftModified, got {other:?}"),
        }
        assert!(target.exists(), "the edited file must still be there");
        assert_eq!(
            std::fs::read_to_string(&target).expect("read"),
            contents,
            "and it must be unchanged"
        );

        std::fs::remove_dir_all(&site.hooks_dir).ok();
    }

    #[test]
    fn uninstalling_a_foreign_hook_does_nothing() {
        let site = temp_site("foreign");
        let target = site.hook_path("post-commit");
        std::fs::write(&target, "#!/bin/sh\necho not ours\n").expect("seed");

        let outcome = uninstall(&site, "post-commit").expect("uninstall");
        assert_eq!(outcome, UninstallOutcome::NothingToDo);
        assert!(target.exists());

        std::fs::remove_dir_all(&site.hooks_dir).ok();
    }

    #[test]
    fn a_configured_hooks_path_is_honoured_and_flagged_as_shared() {
        // Spec 9.3: installing into .git/hooks when core.hooksPath points elsewhere
        // means the hook silently never runs.
        let git_dir = PathBuf::from("/repo/.git");
        let site = HookSite::resolve(&git_dir, Some("../shared-hooks"));
        assert!(site.hooks_dir.ends_with("shared-hooks"));
        assert!(
            site.shared,
            "a configured path is usually shared and must be flagged"
        );

        let default_site = HookSite::resolve(&git_dir, None);
        assert!(default_site.hooks_dir.ends_with("hooks"));
        assert!(!default_site.shared);
    }

    #[test]
    fn an_absolute_hooks_path_is_used_as_is() {
        let git_dir = PathBuf::from("/repo/.git");
        let site = HookSite::resolve(&git_dir, Some("/shared/hooks"));
        assert_eq!(site.hooks_dir, PathBuf::from("/shared/hooks"));
    }

    #[test]
    fn every_managed_hook_name_is_covered_by_the_constant() {
        // The installer loops over MANAGED_HOOKS; a missing entry would silently skip
        // a hook the product claims to install.
        assert_eq!(MANAGED_HOOKS.len(), 3);
        for name in ["post-commit", "post-rewrite", "post-merge"] {
            assert!(MANAGED_HOOKS.contains(&name));
        }
    }
}
